#!/usr/bin/env bash
# Reproduce every number and figure in the DataRanger paper.
#
#   ./reproduce.sh          re-run every analysis from the incident records committed in results/
#                           (about 30 minutes on two cores)
#   ./reproduce.sh full     regenerate the incident records first, then re-run the analyses
#                           (longer: the records take most of the time)
#
# Two inputs are not regenerated by either mode, because they need software or hardware outside
# this container: the LLM proposals (Qwen2.5 through Ollama, run by .github/workflows/llm.yml; the
# responses are in results/llm_responses/) and the Baran corrections (results/baran/, from
# benchmarks/run_baran.py, which needs `pip install raha`). Both are scored here from their saved
# outputs. Every script is deterministic: seeds are fixed, so re-running gives the same numbers,
# except the wall-clock runtimes in results/ablations.json, which depend on the machine.
set -euo pipefail
cd "$(dirname "$0")"
MODE="${1:-analyses}"
step() { printf '\n== %s\n' "$*"; }
gz() { gzip -c "$1" > "$1.gz"; }

step "Unit tests"
python -m pytest -q tests

if [ "$MODE" = "full" ]; then
  step "Detection on all sizes and the real datasets"
  python benchmarks/run_detection.py
  step "Incident records: 150 small and 100 medium instances (Q1-Q3)"
  python benchmarks/run_repair.py 150 100 && gz results/repair_records.jsonl
  step "Incident records: 40 large instances (Q3)"
  python benchmarks/run_repair.py 0 0 40 results/repair_records_large.jsonl && gz results/repair_records_large.jsonl
  step "A year of incidents for the drift experiment (Q5)"
  python benchmarks/run_stream.py
  step "TPC-DS store_sales, scale factor 1, 30 windows x 3 injections (Q4)"
  python benchmarks/run_tpcds.py 1 3
  step "Corrupt control totals: 150 small instances at 5% and 20% corruption (Q8)"
  python benchmarks/run_corrupt.py
  step "Scale: TPC-DS at scale factors 1 and 10, single partitions to 20M rows (Q8; needs about 8 GB RAM)"
  python benchmarks/scale.py tpcds_sf1.duckdb:1 tpcds_sf10.duckdb:10
  step "Independent population for the cohort experiment: 3,000 instances with fresh seeds (Q1; about 45 minutes on two cores)"
  python benchmarks/run_cohorts.py 3000 0 results/cohort_records.jsonl && gz results/cohort_records.jsonl
  step "Harder error families on the 150 small instances, per-channel and per-channel-and-category totals (Q8)"
  python benchmarks/run_hard.py 150
  step "Harder mix on 500 independent instances per evidence granularity, for certification per table (Q8, Table 6; about two hours on two cores)"
  python benchmarks/run_hard_cohort.py 500 && gz results/hard_cohort_records.jsonl && rm results/hard_cohort_records.jsonl
  step "Verification pushed down into DuckDB on partitions of 1 to 50 million rows (Q8; needs about 6 GB of disk)"
  python benchmarks/pushdown.py
fi

step "Incident-level calibration on the 250-instance benchmark: baselines, fixed thresholds, held-out error types (Q2, Q3, Q5)"
python benchmarks/analyze_repair.py
step "Dependence between incidents of one table: intraclass correlation and design effect (Q1)"
python benchmarks/analyze_guarantee.py
step "Calibration cohorts of 100, 200 and 400 tables against the held-out tables (Q1, Figure 2)"
python benchmarks/analyze_cohorts.py
step "Evidence ablation at the incident level (supplementary; also provides helpers for the per-table analysis)"
python benchmarks/analyze_evidence.py
step "A tolerance tuned on labels; fixed candidate with different accepting scores at the incident level (Q3)"
python benchmarks/analyze_controls.py
step "Certification per table on 1,000 held-out tables: main comparison and what the evidence adds (Q1, Tables 1 and 2)"
python benchmarks/analyze_cluster.py
step "Escalation reasons, partition totals, and the harder mix certified per table (Q1, Q3, Q8, Table 6)"
python benchmarks/analyze_cluster_extra.py
step "Harder error families at the incident level on 150 instances (supplementary; Table 6 comes from the per-table analysis above)"
python benchmarks/analyze_hard.py
step "TPC-DS: in-domain calibration, transfer, fixed tolerances (Q4, Table 3)"
python benchmarks/analyze_tpcds.py
step "Transfer to large tables (supplementary)"
python benchmarks/analyze_large.py
step "Drift and repair memory (Q5)"
python benchmarks/analyze_stream.py
step "Reconciliation monitor ablation, label budgets, invariant ablation, runtimes (Q8)"
python benchmarks/ablation_reconcile.py
python benchmarks/ablations.py
step "Corrupt control totals (Q8)"
python benchmarks/analyze_corrupt.py
step "Real datasets, earlier cell-level protocol (supplementary)"
python benchmarks/run_cells.py results/baran
step "Real datasets: matched budgets, other proposers through the gate, same proposals with different scores (Q7, Table 5)"
# Baran corrections at budgets 20 (5 seeds), 50, 100 and 200 (3 seeds each) are committed in results/baran/ (benchmarks/run_baran.py).
python benchmarks/run_cells2.py results/baran

step "LLM proposers and the self-checking baseline (Q6, Table 4)"
# The model responses from the Actions run (llm-results branch, run 40882980162) are committed here.
python benchmarks/eval_llm.py results/llm_responses

step "Figures"
python benchmarks/figures.py results figures
step "Tables 1, 2, 5 and 6 of the paper as LaTeX rows"
python benchmarks/paper_tables.py > results/paper_tables.tex
echo; echo "Done. Numbers are in results/*.json, table rows in results/paper_tables.tex, figures in figures/."
